CREATE OR REPLACE FUNCTION public.icash_discovery_filter_state_v2(p_account uuid, p_revision uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;stats jsonb;result jsonb;
begin
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return null;end if;
 perform public.icash_refresh_opportunity_outcomes(p_account);
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page then raise exception 'Filter configuration changed';end if;
 insert into public.icash_discovery_filter_cursors(account_id,revision,zip,strategy,next_page)
 select p_account,p_revision,c.zip,strategy,case when strategy='baseline' then c.next_page else 1 end
 from unnest(array['baseline','vacant','absentee','repairs']) strategy on conflict do nothing;
 stats:=public.icash_discovery_filter_feedback(p_account,c.zip);
 select jsonb_agg(s.value||jsonb_build_object('nextPage',cur.next_page,'exhausted',cur.exhausted,'pages',cur.pages)) into result
 from jsonb_array_elements(stats) s join public.icash_discovery_filter_cursors cur on cur.strategy=s.value->>'strategy'
 where cur.account_id=p_account and cur.revision=p_revision and cur.zip=c.zip;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.icash_finish_dealmachine_request(p_request uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text;v jsonb;clean jsonb;
begin
 if coalesce(p_result->>'outcome','') not in ('response','http_error','unknown') or jsonb_typeof(p_result) is distinct from 'object' then return false;end if;
 clean:=jsonb_build_object('outcome',p_result->>'outcome');
 foreach k in array array['httpStatus','returned','creditsUsed','minuteRemaining','dayRemaining','retryAfter'] loop
  v:=p_result->k;
  if v is not null and v<>'null'::jsonb then
   if jsonb_typeof(v)<>'number' or v::text !~ '^[0-9]{1,10}$' then return false;end if;
   clean:=clean||jsonb_build_object(k,v);
  end if;
 end loop;
 update icash_research_private.requests set finished_at=now(),result=clean where id=p_request and admitted and finished_at is null;
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_discovery_inventory(p_account uuid, p_revision uuid, p_page integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;cur record;cached jsonb;n integer:=0;streak integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or not c.enabled or not c.auto_enabled or c.data_rights_until<=now()
 or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
 or not public.icash_membership_work_allowed(p_account) then return 'inventory_held';end if;
 if exists(select 1 from public.icash_operation_spend where operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and state<>'reserved') then return 'awaiting_reconciliation';end if;
 perform public.icash_expand_inventory_markets(p_account);
 select count(*) into streak from (select queued_properties,returned_properties,duplicate_properties from public.icash_discovery_inventory_receipts where account_id=p_account and revision=p_revision order by created_at desc limit 3) recent
 where queued_properties=0 and returned_properties=duplicate_properties;
 if streak=3 then
  update public.icash_inventory_markets set next_scan_at=greatest(next_scan_at,now()+interval '6 hours') where account_id=p_account and zip=c.zip;
  update public.icash_discovery_configs set exhausted=true where account_id=p_account;
  if public.icash_rotate_inventory_market(p_account) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return 'ready';end if;
 perform public.icash_discovery_filter_state_v2(p_account,p_revision,p_page);
 if c.research_version in (1,2) then return 'ready';end if;
 for cur in select * from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted order by strategy for update loop
  loop
   cached:=public.icash_known_assigned_discovery_page(c.zip,cur.strategy,cur.next_page,c.per_page);
   exit when cached is null;
   update public.icash_discovery_filter_cursors set next_page=next_page+1,skipped_assigned_pages=skipped_assigned_pages+1,exhausted=not (cached->>'hasNextPage')::boolean
   where account_id=p_account and revision=p_revision and strategy=cur.strategy;
   cur.next_page:=cur.next_page+1;n:=n+1;
   if n>=64 then return 'inventory_advancing';end if;
   exit when not (cached->>'hasNextPage')::boolean;
  end loop;
 end loop;
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
  if exists(select 1 from public.icash_discovery_configs where account_id=p_account and revision<>p_revision) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 return 'ready';
end $function$

CREATE OR REPLACE FUNCTION public.icash_take_dealmachine_request()
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.icash_dealmachine_request_budget;
begin
 select * into b from public.icash_dealmachine_request_budget where id=1 for update;
 if not found then return false; end if;
 if b.minute_start<=now()-interval '1 minute' then b.minute_start:=now();b.minute_used:=0;end if;
 if b.day_start<=now()-interval '24 hours' then b.day_start:=now();b.day_used:=0;end if;
 if b.minute_used>=b.minute_limit or b.day_used>=b.day_limit then return false;end if;
 update public.icash_dealmachine_request_budget set minute_start=b.minute_start,minute_used=b.minute_used+1,day_start=b.day_start,day_used=b.day_used+1 where id=1;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_take_dealmachine_request(p_kind text, p_account uuid, p_operation text, p_request uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed boolean;
begin
 if p_request is null or p_kind not in ('search_estimate','property_search','owner_preview','owner_lookup','exclusion_create','exclusion_sync','geography','buyer_estimate','buyer_search','property_lookup','photo') or length(coalesce(p_operation,''))>200 then return false;end if;
 -- Lock the existing limiter first; its counters, windows and ceilings are unchanged.
 perform 1 from public.icash_dealmachine_request_budget where id=1 for update;
 if exists(select 1 from icash_research_private.requests where id=p_request) then return false;end if;
 allowed:=public.icash_take_dealmachine_request();
 insert into icash_research_private.requests(id,kind,account_id,operation_key,admitted,result)
 values(p_request,p_kind,p_account,p_operation,allowed,case when allowed then null else '{"outcome":"quota_wait"}'::jsonb end);
 return allowed;
end $function$
